function parseTime(value){if(value==null||value==='')return '';if(typeof value==='number'){if(!Number.isFinite(value)||value<0)return '';const seconds=Math.round((value%1)*86400)%86400;return [Math.floor(seconds/3600),Math.floor(seconds%3600/60),seconds%60].map(x=>String(x).padStart(2,'0')).join(':')}const match=String(value).trim().match(/^(\d{1,2}):(\d{2})(?::(\d{2}))?$/);if(!match||Number(match[1])>23||Number(match[2])>59||Number(match[3]||0)>59)return '';return [match[1],match[2],match[3]||'00'].map(x=>String(x).padStart(2,'0')).join(':')}
