const holidayCache=new Map();function holidaySet(year){if(holidayCache.has(year))return holidayCache.get(year);const fixed=['01-01','04-21','05-01','09-07','10-12','11-02','11-15','11-20','12-25'].map(md=>`${year}-${md}`);const easter=easterSunday(year).toISOString().slice(0,10),holidays=new Set([...fixed,shiftIsoDay(easter,-2)]);holidayCache.set(year,holidays);return holidays}
