const businessAgeCache=new Map();function businessDaysSince(capturedAt,asOf,channel){if(!/^\d{4}-\d{2}-\d{2}$/.test(capturedAt)||capturedAt>=asOf)return 0;const key=capturedAt+'|'+asOf+'|'+storeState(channel);if(businessAgeCache.has(key))return businessAgeCache.get(key);let count=0,cursor=shiftIsoDay(capturedAt,1);while(cursor<=asOf){const weekday=new Date(`${cursor}T12:00:00Z`).getUTCDay();if(weekday!==0&&weekday!==6&&!isHoliday(cursor,channel))count++;cursor=shiftIsoDay(cursor,1)}if(businessAgeCache.size>5000)businessAgeCache.clear();businessAgeCache.set(key,count);return count}
function isOpenOrder(row){return isUnbilled(row)&&!normalize(row.status).includes('cancel')}
