function overdueStoreGroups(rows){const stores=new Map(),aliasesByCanonical=new Map();for(const [rawId,rawName]of Object.entries(base.stores||{})){const id=canonicalOverdueStoreCode(rawId),name=id==='25915'?'Caratinga':String(rawName||directory[id]?.unit||id);if(!stores.has(id))stores.set(id,name);if(id!==rawId){if(!aliasesByCanonical.has(id))aliasesByCanonical.set(id,new Set());aliasesByCanonical.get(id).add(rawId)}}for(const row of base.rows){const rawId=code(row.channel),id=canonicalOverdueStoreCode(rawId);if(!stores.has(id))stores.set(id,id==='25915'?'Caratinga':mapped(row.channel).unit||row.channel);if(id!==rawId){if(!aliasesByCanonical.has(id))aliasesByCanonical.set(id,new Set());aliasesByCanonical.get(id).add(rawId)}}const isStoreMode=$('#overdueScope').value==='store',selected=canonicalOverdueStoreCode($('#overdueStore').value);if(isStoreMode&&!$('#overdueStore').value)return[];return [...stores].filter(([id])=>(!isStoreMode||id===selected)&&(!activeState||storeState(id)===activeState)).map(([id,name])=>{const orders=rows.filter(row=>canonicalOverdueStoreCode(row.channel)===id),storeName=id==='25915'?'Caratinga':String(name||directory[id]?.unit||id),storeKeys=new Set([id,...(overdueStoreAliases[id]||[]),...(aliasesByCanonical.get(id)||[])]),keys=new Set([normalize(storeName),...([...storeKeys].flatMap(storeCode=>[normalize(storeCode),normalize(`${storeCode} - ${storeName}`),normalize(`${storeCode} - ${base.stores?.[storeCode]||storeName}`)]))]),users=overdueUsers.filter(user=>(user.stores||[]).some(store=>keys.has(normalize(store)))).map(user=>user.name);return{code:id,name:storeName,orders,users}}).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'))}
