function overduePageGroups(groups){const pages=[];let page=[],height=0;const add=(group,orders,continuation=false)=>{const lines=1+Math.max(1,orders.length);if(page.length&&height+lines>35){pages.push(page);page=[];height=0}page.push({...group,displayOrders:orders,continuation});height+=lines};for(const group of groups){if(!group.orders.length){add(group,[]);continue}for(let offset=0;offset<group.orders.length;offset+=34)add(group,group.orders.slice(offset,offset+34),offset>0)}if(page.length)pages.push(page);return pages.length?pages:[[]]}
function overdueImagePageCount(groups){return overduePageGroups(groups).length}
