root.querySelectorAll('[data-overdue-type]').forEach(button=>button.onclick=()=>{overdueType=button.dataset.overdueType;overduePageIndex=0;renderOverdueShare()});$('#overdueScope').onchange=()=>{overduePageIndex=0;renderOverdueShare()};$('#overdueStore').onchange=()=>{overduePageIndex=0;renderOverdueShare()};$('#overduePrev').onclick=()=>{overduePageIndex--;renderOverdueShare()};$('#overdueNext').onclick=()=>{overduePageIndex++;renderOverdueShare()};$('#copyOverdueMessage').onclick=async()=>{if(!canImport)return;try{await navigator.clipboard.writeText($('#overdueMessage').value);toast('Mensagem copiada.')}catch{$('#overdueMessage').focus();$('#overdueMessage').select();toast('Selecione e copie a mensagem.')}};$('#openOverdueWhatsApp').onclick=()=>{if(!canImport)return;const url='https://wa.me/?text='+encodeURIComponent($('#overdueMessage').value);window.open(url,'_blank','noopener,noreferrer')};$('#downloadOverdueImage').onclick=()=>{if(!canImport)return;$('#overdueCanvas').toBlob(blob=>{if(!blob)return;const pages=overdueImagePageCount(overdueStoreGroups(overdueRows())),suffix=pages>1?`-pagina-${overduePageIndex+1}-de-${pages}`:'';saveBlob(blob,`pedidos-em-atraso-${today()}${suffix}.png`)},'image/png')};
const orderFields=[['id','Código do pedido'],['date','Data do pedido'],['time','Hora de entrada'],['cycle','Ciclo Captação'],['channel','Loja / Canal'],['segment','Papel do revendedor'],['status','Situação comercial'],['payment','Plano de pagamento'],['delivery','Tipo de entrega'],['omni','Omnichannel'],['fiscal','Situação fiscal'],['period','Faixa de horário']];
const columnFilters=Object.fromEntries(orderFields.map(([key])=>[key,'']));
function orderFieldValue(r,key){if(key==='time')return parseTime(r.time)?parseTime(r.time).slice(0,5):'Não informado';if(key==='period')return !parseTime(r.time)?'Sem horário':parseTime(r.time)>'18:00:00'?'Após as 18h':'Até as 18h';return key==='omni'?(r.external?'Sim':'Não'):String(r[key]||'Não informado')}
function updateColumnOptions(){const pool=base.rows.filter(isUnbilled);for(const [key]of orderFields){if(key==='id')continue;const select=$('#col-'+key);if(!select)continue;const values=(key==='period'?['Após as 18h','Até as 18h','Sem horário']:[...new Set(pool.map(r=>orderFieldValue(r,key)))]).sort((a,b)=>a.localeCompare(b,'pt-BR',{numeric:true}));if(!values.includes(columnFilters[key]))columnFilters[key]='';const html='<option value="">Todos</option>'+values.map(v=>`<option value="${esc(v)}">${esc(key==='date'?br(v):key==='channel'?channelLabel(v):v)}</option>`).join('');if(select.innerHTML!==html)select.innerHTML=html;select.value=columnFilters[key]}}
function ensureOrderHeader(){if($('#ordersTable').tHead)return;$('#ordersTable').innerHTML='<thead><tr>'+orderFields.map(([key,label])=>`<th scope="col"><span>${label}</span>${key==='id'?`<input id="col-id" type="search" aria-label="Filtrar código do pedido" placeholder="Código…">`:`<select id="col-${key}" aria-label="Filtrar ${esc(label)}"><option value="">Todos</option></select>`}</th>`).join('')+'</tr></thead><tbody></tbody>';for(const [key]of orderFields){const input=$('#col-'+key);input[key==='id'?'oninput':'onchange']=()=>{columnFilters[key]=input.value.trim();orderPage=1;renderOrders()}}updateColumnOptions()}
function detailRows(){return selected().filter(r=>orderFields.every(([key])=>!columnFilters[key]||(key==='id'?r.id.includes(columnFilters.id):orderFieldValue(r,key)===columnFilters[key]))).sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id,undefined,{numeric:true}))}
function renderOrders(){ensureOrderHeader();$('#orderPeriodQuick').value=columnFilters.period;const rows=detailRows(),pages=Math.max(1,Math.ceil(rows.length/50));orderPage=Math.min(Math.max(1,orderPage),pages);const slice=rows.slice((orderPage-1)*50,orderPage*50);$('#ordersTable tbody').innerHTML=slice.length?slice.map(r=>`<tr><td class="order-code">${esc(r.id)}</td><td>${br(r.date)}</td><td>${esc(orderFieldValue(r,'time'))}</td><td>${esc(r.cycle||'Não informado')}</td><td>${esc(channelLabel(r.channel))}</td><td>${esc(r.segment||'Não informado')}</td><td><span class="status-dot ${normalize(r.status)}"></span>${esc(r.status)}</td><td>${esc(r.payment||'Não informado')}</td><td>${esc(r.delivery||'Não informado')}</td><td>${r.external?'Sim':'Não'}</td><td><span class="unbilled-badge">${esc(r.fiscal)}</span></td><td>${esc(orderFieldValue(r,'period'))}</td></tr>`).join(''):'<tr><td colspan="12" class="empty">Nenhum pedido para os filtros selecionados.</td></tr>';$('#ordersCount').textContent=rows.length?`${rows.length} pedidos encontrados · exibindo ${(orderPage-1)*50+1} a ${Math.min(orderPage*50,rows.length)}`:'0 pedidos encontrados';$('#pageNumber').textContent=`${orderPage} / ${pages}`;$('#prevPage').disabled=orderPage<=1;$('#nextPage').disabled=orderPage>=pages}
$('#orderPeriodQuick').onchange=()=>{columnFilters.period=$('#orderPeriodQuick').value;$('#col-period').value=columnFilters.period;orderPage=1;renderOrders()};
$('#clearColumnFilters').onclick=()=>{for(const [key]of orderFields){columnFilters[key]='';const el=$('#col-'+key);if(el)el.value=''}orderPage=1;renderOrders()};
$('#prevPage').onclick=()=>{orderPage--;renderOrders()};$('#nextPage').onclick=()=>{orderPage++;renderOrders()};$('#ordersCsv').onclick=()=>{const rows=detailRows();const quote=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';const matrix=[['Código do pedido','Data do pedido','Hora de entrada','Ciclo Captação','Loja / Canal','Papel do revendedor','Situação comercial','Plano de pagamento','Tipo de entrega','Omnichannel','Situação fiscal','Faixa de horário'],...rows.map(r=>[r.id,br(r.date),orderFieldValue(r,'time'),r.cycle||'Não informado',channelLabel(r.channel),r.segment,r.status,r.payment,r.delivery,r.external?'Sim':'Não',r.fiscal,orderFieldValue(r,'period')])];saveBlob(new Blob(['\ufeff'+matrix.map(r=>r.map(quote).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'pedidos-nao-faturados-'+today()+'.csv')};
root.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{orderType=b.dataset.type;if($('#countedView').hidden)view('orders');render();renderCountedOverdue()});
root.querySelectorAll('[data-state]').forEach(button=>button.onclick=()=>{activeState=button.dataset.state;if($('#ordersView').hidden&&$('#dashboardView').hidden&&$('#countedView').hidden)view('orders');render();renderCountedOverdue()});
function closeMenu(){portalBody.classList.remove('menu-open');$('#menuOverlay').hidden=true;$('#menuToggle').setAttribute('aria-expanded','false')}
$('#menuToggle').onclick=()=>{const open=portalBody.classList.toggle('menu-open');$('#menuOverlay').hidden=!open;$('#menuToggle').setAttribute('aria-expanded',String(open))};$('#menuOverlay').onclick=closeMenu;root.querySelectorAll('[data-view],[data-type],[data-state]').forEach(b=>b.addEventListener('click',()=>{if(window.innerWidth<=760)closeMenu()}));listenRoot('keydown',e=>{if(e.key==='Escape')closeMenu()});
async function init(){await synchronize();if(stopped)return;options();render();if(!hasExternalNavigation)view('orders');accessControls();syncTimer=setInterval(()=>void synchronize(),10000);}const ready=init();

